  "ancient-05": {"birth": "450년대 추정", "death": "519년(문자명왕 28)", "birthplace": "고구려", "sources": [["한국민족문화대백과사전", "https://encykorea.aks.ac.kr/Article/E0019639"]], "family": "아버지 고조다(조다) · 할아버지 장수왕", "factSources": {"birth": [["나무위키 · 문자명왕", "https://namu.wiki/w/%EB%AC%B8%EC%9E%90%EB%AA%85%EC%99%95"]], "family": [["한국민족문화대백과사전", "https://encykorea.aks.ac.kr/Article/E0019639"]]}, "activities": [["주요 활동과 기록", "재위 중 중국 남북조 여러 왕조에 사신을 보냈다. 부여의 왕이 고구려에 투항한 일도 이 시기 기록에 전한다."]]},
  "ancient-06": {"birth": "미상", "death": "331년", "birthplace": "고구려", "sources": [["한국민족문화대백과사전", "https://encykorea.aks.ac.kr/Article/E0020017"]], "family": "아버지 고돌고 · 배우자 주씨 · 아들 고국원왕(고사유), 고무", "factSources": {"family": [["나무위키 · 미천왕", "https://namu.wiki/w/%EB%AF%B8%EC%B2%9C%EC%99%95"]]}, "activities": [["주요 활동과 기록", "낙랑군과 대방군이 자리하던 지역에 진출했다. 왕위에 오르기 전의 이야기도 『삼국사기』에 전한다."]]},
  "ancient-07": {"birth": "미상", "death": "391년", "sources": [["한국민족문화대백과사전", "https://encykorea.aks.ac.kr/Article/E0003338"]], "family": "아버지 고국원왕 · 형 소수림왕 · 아들 광개토대왕(고담덕)", "factSources": {"family": [["나무위키 · 고국양왕", "https://namu.wiki/w/%EA%B3%A0%EA%B5%AD%EC%96%91%EC%99%95"]]}, "activities": [["주요 활동과 기록", "소수림왕의 뒤를 이었다. 재위 중 후연과 대립하고 신라와 외교 관계를 맺었다."]]},
  "ancient-08": {"birth": "579년 · 월일 미상", "death": "631년", "sources": [["한국민족문화대백과사전", "https://encykorea.aks.ac.kr/Article/E0013838"]], "activities": [["주요 활동과 기록", "『일본서기』에는 610년 일본에 갔으며 종이와 먹을 만드는 기술에 밝았다고 기록돼 있다."]]},
